// Question 1: Memory Allocation (First Fit & Worst Fit)
#include <iostream>
using namespace std;

void firstFitFunc(int block[], int nBlocks, int process[], int nProcesses) {
    int blockCopy[nBlocks];
    int allocation[nProcesses];

    for (int i = 0; i < nBlocks; i++) {
        blockCopy[i] = block[i];
    }
    for (int i = 0; i < nProcesses; i++) {
        allocation[i] = -1;
    }

    for (int i = 0; i < nProcesses; i++) {
        for (int j = 0; j < nBlocks; j++) {
            if (blockCopy[j] >= process[i]) {
                allocation[i] = j;
                blockCopy[j] -= process[i];
                break;
            }
        }
    }

    cout << "\nFirst Fit Allocation:\n";
    for (int i = 0; i < nProcesses; i++) {
        cout << "P" << i + 1 << " (" << process[i] << ") -> ";
        if (allocation[i] != -1)
            cout << "Block " << allocation[i] + 1;
        else
            cout << "Not Allocated";
        cout << endl;
    }
}

void worstFitFunc(int block[], int nBlocks, int process[], int nProcesses) {
    int blockCopy[nBlocks];
    int allocation[nProcesses];

    for (int i = 0; i < nBlocks; i++) {
        blockCopy[i] = block[i];
    }
    for (int i = 0; i < nProcesses; i++) {
        allocation[i] = -1;
    }

    for (int i = 0; i < nProcesses; i++) {
        int worstIndex = -1;

        for (int j = 0; j < nBlocks; j++) {
            if (blockCopy[j] >= process[i]) {

                if (worstIndex == -1 || blockCopy[j] > blockCopy[worstIndex]) {
                    worstIndex = j;
                }
            }
        }

        if (worstIndex != -1) {
            allocation[i] = worstIndex;
            blockCopy[worstIndex] -= process[i];
        }
    }

    cout << "\nWorst Fit Allocation:\n";
    for (int i = 0; i < nProcesses; i++) {
        cout << "P" << i + 1 << " (" << process[i] << ") -> ";
        if (allocation[i] != -1)
            cout << "Block " << allocation[i] + 1;
        else
            cout << "Not Allocated";
        cout << endl;
    }
}

int main() {
    int nBlocks, nProcesses;

    cout << "Enter number of memory blocks: ";
    cin >> nBlocks;

    int block[nBlocks];
    cout << "Enter block sizes:\n";
    for (int i = 0; i < nBlocks; i++) {
        cin >> block[i];
    }

    cout << "Enter number of processes: ";
    cin >> nProcesses;

    int process[nProcesses];
    cout << "Enter process sizes:\n";
    for (int i = 0; i < nProcesses; i++) {
        cin >> process[i];
    }

    firstFitFunc(block, nBlocks, process, nProcesses);
    worstFitFunc(block, nBlocks, process, nProcesses);

    return 0;
}

